Theorem grow2 : PMA.opdel_spec L ar HI -> forall (fx6 : FPState) R M model K LBX FF LK Aw cr v b k stk sp r p1 p2 p3 m n t B R6 M6 model6 Aw6,
    ri_inv HI (PM.vec_own b k ++ LBX) FF LK cr Aw M (vml_of model) -> K [] -> PMSPA.entryA PeCLayoutA.CADDR_A L ar R M sp r 0 ->
    PMSPA.aobjA FF v 24 -> v mod 8 = 0 -> Z.of_nat (length stk) = 2 ^ k -> 0 <= k <= 10 -> 0 <= p1 < 2 ^ 47 -> 0 <= p2 < 2 ^ 47 -> 0 <= p3 < 2 ^ 47 ->
    PMAEUGS.gmid L ar HI R M model LBX FF LK Aw cr v b k stk sp p1 p2 p3 m n t B R6 M6 model6 Aw6 ->
    (forall (fx' : FPState) R' M' model' LK' Aw' b', regs_preserved R R' -> PM.vec_at RSEGS PMSPA.accA PMSPA.annA M' v b' (k + 1) (stk ++ [PM.PS m n t 0]) ->
        PMSPA.accA M' v 24 -> L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 0) [(v, 24)] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PM.vec_own b' (k + 1) ++ LBX) FF LK' (adebit L cr (32 * 2 ^ (k + 1))) Aw' M' (vml_of model') ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' r M' model') K) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx6 R6 0xb2068 M6 model6) K.
Proof.
